-- Script 200 · parte 7 de 16 · Organización 2: detalle contable de las compras (ACT_DETCON_COMPRAS y _PARTE_2), 5426 líneas.
-- Se ejecuta después del script 198 (compras). Se puede ejecutar de nuevo: la segunda vez solo actualiza.
alter table public.compra_lineas add column if not exists cuenta_codigo_anterior text;
alter table public.compra_lineas add column if not exists version_cuenta_anterior integer;
alter table public.compra_lineas add column if not exists centro_costo_anterior text;
alter table public.compra_lineas add column if not exists debe_anterior numeric(18, 2);
alter table public.compra_lineas add column if not exists haber_anterior numeric(18, 2);
alter table public.compra_lineas add column if not exists reconstruida boolean not null default false;
set lock_timeout = '20s';

do $detcon$
declare
  v_org bigint; v_loc bigint; v_kc bigint; v_may bigint; r record; v_n int := 0; v_a int := 0; v_cen int := 0; v_sin_compra int; v_sin_cuenta text; v_rec int;
begin
  select id into v_org from public.organizaciones where codigo = '2';
  if v_org is null then raise notice 'No existe la organización 2.'; return; end if;

  -- a) Centros de costo de las líneas que no existen en el catálogo de centros de la localidad: se crean (el 0 es «sin centro»).
  for r in select * from (values (1, '308'), (1, '303'), (1, '307'), (1, '10601'), (1, '2010101'), (1, '30104'), (1, '30402'), (1, '2010201'), (1, '306'), (1, '10602'), (1, '30401'), (1, '102'), (1, '2010206'), (1, '101'), (1, '2020501'), (1, '2020308'), (1, '2010203'), (2, '309')) as x(loc, codigo) loop
    select id into v_loc from public.localidades where organizacion_id = v_org and correlativo = r.loc;
    if v_loc is null then continue; end if;
    v_kc := null;
    select id into v_kc from public.catalogos_centros where localidad_id = v_loc order by (version = 1) desc, activo desc, version limit 1;
    if v_kc is null then
      insert into public.catalogos_centros (organizacion_id, localidad_id, version, fecha_del) values (v_org, v_loc, 1, date '2018-01-01') returning id into v_kc;
    end if;
    if exists (select 1 from public.centros_costo where catalogo_id = v_kc and codigo = r.codigo) then continue; end if;
    v_may := null;
    select id into v_may from public.centros_costo where catalogo_id = v_kc and length(codigo) < length(r.codigo) and left(r.codigo, length(codigo)) = codigo order by length(codigo) desc limit 1;
    insert into public.centros_costo (organizacion_id, catalogo_id, codigo, nombre, centro_mayor_id, integra, centro_anterior)
    values (v_org, v_kc, r.codigo, 'CENTRO DE COSTO ' || r.codigo || ' (CREADO AL MIGRAR COMPRAS)', v_may, true, r.codigo);
    v_cen := v_cen + 1;
  end loop;

  -- Las validaciones de la pantalla (compra anulada o con partida) se suspenden durante la carga.
  alter table public.compra_lineas disable trigger compra_lineas_validar;
  -- Las líneas que el script 168 reconstruyó en estas compras se reemplazan por las del sistema anterior.
  delete from public.compra_lineas cl using (values (1, 11100), (1, 11101), (1, 11102), (1, 11103), (1, 11104), (1, 11105), (1, 11106), (1, 11107), (1, 11108), (1, 11109), (1, 11110), (1, 11111), (1, 11112), (1, 11113), (1, 11114), (1, 11115), (1, 11116), (1, 11117), (1, 11118), (1, 11119), (1, 11120), (1, 11121), (1, 11122), (1, 11123), (1, 11124), (1, 11125), (1, 11126), (1, 11127), (1, 11128), (1, 11129), (1, 11130), (1, 11131), (1, 11132), (1, 11133), (1, 11134), (1, 11135), (1, 11136), (1, 11137), (1, 11138), (1, 11139), (1, 11140), (1, 11141), (1, 11142), (1, 11143), (1, 11144), (1, 11145), (1, 11146), (1, 11147), (1, 11148), (1, 11149), (1, 11150), (1, 11151), (1, 11152), (1, 11153), (1, 11154), (1, 11155), (1, 11156), (1, 11157), (1, 11158), (1, 11159), (1, 11160), (1, 11161), (1, 11162), (1, 11163), (1, 11164), (1, 11165), (1, 11166), (1, 11167), (1, 11168), (1, 11169), (1, 11170), (1, 11171), (1, 11172), (1, 11173), (1, 11174), (1, 11175), (1, 11176), (1, 11177), (1, 11178), (1, 11179), (1, 11180), (1, 11181), (1, 11182), (1, 11183), (1, 11184), (1, 11185), (1, 11186), (1, 11187), (1, 11188), (1, 11189), (1, 11190), (1, 11191), (1, 11192), (1, 11193), (1, 11194), (1, 11195), (1, 11196), (1, 11197), (1, 11198), (1, 11199), (1, 11200), (1, 11201), (1, 11202), (1, 11203), (1, 11204), (1, 11205), (1, 11206), (1, 11207), (1, 11208), (1, 11209), (1, 11210), (1, 11211), (1, 11212), (1, 11213), (1, 11214), (1, 11215), (1, 11216), (1, 11217), (1, 11218), (1, 11219), (1, 11220), (1, 11221), (1, 11222), (1, 11223), (1, 11224), (1, 11225), (1, 11226), (1, 11227), (1, 11228), (1, 11229), (1, 11230), (1, 11231), (1, 11232), (1, 11233), (1, 11234), (1, 11235), (1, 11236), (1, 11237), (1, 11238), (1, 11239), (1, 11240), (1, 11241), (1, 11242), (1, 11243), (1, 11244), (1, 11245), (1, 11246), (1, 11247), (1, 11248), (1, 11249), (1, 11250), (1, 11251), (1, 11252), (1, 11253), (1, 11254), (1, 11256), (1, 11257), (1, 11258), (1, 11259), (1, 11260), (1, 11261), (1, 11262), (1, 